                    satisfied = True
                if lit < 0 and not val:
                    satisfied = True
                if satisfied:
                    break
            if not satisfied:
                ok = False
                break
        if ok:
            return True
    return False

def solve_exact_cover(instance):
    u = instance["universe_size"]
    sets = instance["sets"]
    n_sets = len(sets)
    # brute force over subsets (limit to small sizes)
    for r in range(n_sets + 1):
        for combo in itertools.combinations(range(n_sets), r):
