def solve_exact_cover(instance):
    u = instance["universe_size"]
    sets = instance["sets"]
    n_sets = len(sets)
    for r in range(n_sets+1):
        for combo in itertools.combinations(range(n_sets), r):
            covered = [0]*u
            good = True
            for idx in combo:
                for e in sets[idx]:
                    if covered[e]:
                        good=False; break
                    covered[e]=1
                if not good:
                    break
            if good and all(covered):
                return True
    return False
